insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (5,'Circunferencia del piso','Acá el piso dibuja una circunferencia: parate adentro y recorré el borde, que es lo más cerca que vas a estar de un código con sentido.',-34.609512,-58.389489,15,'PISO05','`class` · Ya hay suficientes moldes para crear el mapa. La plaza se dibuja en la pantalla como un diagrama de flujo.','Desde el punto anterior, este punto queda hacia el sur, a unos 30 m.');
