insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (6,'Fuente Principal','Con el Congreso de fondo y las fuentes detrás, entre un farol de varios brazos y otro pedestal con vasija, hay una reja baja verde y palomas con más prioridad que vos. Es la fuente principal: ubicate a su derecha.',-34.609513,-58.390162,15,'FUENTE06','`loop` · Paso a paso, el sistema recupera su ritmo. El Glitch repite un mismo mensaje en bucle: «línea 1, línea 1, línea 1…».','Desde el punto anterior, este punto queda hacia el oeste, a unos 60 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (6,0,'opcion_multiple','¿Qué paradigma se basa en instrucciones paso a paso?','["Lógico", "Declarativo", "Imperativo", "Funcional"]'::jsonb,'Imperativo');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (6,1,'texto_libre','¿Cuántas veces se ejecuta este bucle?  for (i = 0; i < 5; i++)',null,'5|cinco');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (7,'Entre Fuente y Estatua','Una vereda larga de baldosas con bancos blancos de cemento en fila, un farol dorado en el borde y una reja alta que separa el camino del Congreso. Estás entre la fuente y la estatua.',-34.609555,-58.39074,15,'ESTATUA07','`private` · Los datos internos quedan a salvo tras una puerta que solo el sistema puede abrir. El Glitch retrocede.','Desde el punto anterior, este punto queda hacia el oeste, a unos 55 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (7,0,'opcion_multiple','¿Qué elemento de la POO protege los datos internos de un objeto?','["Herencia", "Encapsulamiento", "Polimorfismo", "Abstracción"]'::jsonb,'Encapsulamiento');
