insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (8,'Sur de la Estatua','Buscá la estatua y caminá hacia el sur, dándole la espalda al Congreso.',-34.609976,-58.39093,15,'SUR08','`query` · Ahora el sistema pide qué resultado quiere sin explicar cada paso. Una nota de la Arquitecta: «El Glitch no es un virus».','Desde el punto anterior, este punto queda hacia el sur, a unos 50 m.');
