insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (9,'Estatua y Congreso','La escalinata del Congreso asomando atrás. Mirá el piso: hay una tapa de hierro con letras grabadas. Entre la estatua y el Congreso, pegadito a la reja.',-34.609702,-58.391206,15,'CONGRESO09','`recursion` · Cada fragmento guarda un recuerdo de los anteriores, como una función que se llama a sí misma. Falta poco.','Desde el punto anterior, este punto queda hacia el noroeste, a unos 40 m.');
