insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (10,'Monumento Ricardo Balbín','Troncos enormes que tienen más historial que un repo de 2010. Buscá el monumento a Ricardo Balbín y pasá a su izquierda.',-34.609887,-58.389671,15,'BALBIN10','`prolog` · Aparecen reglas escritas en lógica. Una dice: «Si un comentario no se cierra, todo lo que sigue se ignora».','Desde el punto anterior, este punto queda hacia el este, a unos 140 m.');
