insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (11,'Biblioteca y Estatua','Entre la historia y los libros... ubicate justo en el medio entre la biblioteca y la estatua.',-34.610029,-58.391016,15,'BIBLIO11','`abstract` · Solo queda lo esencial. Detrás de todo el código hay una única línea que nadie había leído.','Desde el punto anterior, este punto queda hacia el oeste, a unos 125 m.');
